package carbon

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
	"syscall"
	"testing"
	"time"

	"github.com/go-graphite/go-carbon/internal/storecopy"
)

// Opt-in scale measurement: real carbonserver HTTP reads contend with whole
// checkpoint transfers on one source. The fixture is generated by store-copy.
func TestStoreCopyReadLoadBenchmark(t *testing.T) {
	fixture := os.Getenv("GO_CARBON_COPY_FIXTURE")
	if fixture == "" {
		t.Skip("set GO_CARBON_COPY_FIXTURE to the 1M metric fixture root")
	}
	path, cfg := sharedAppConfig(t)
	cfg.Whisper.StoreEncoding = "exact"
	cfg.Whisper.StoreDir = filepath.Join(fixture, "live")
	cfg.Whisper.StoreCacheSize = 16 << 20
	cfg.Whisper.StoreMemTableSize = 1 << 20
	cfg.Common.MetricInterval = &Duration{time.Hour}
	cfg.Common.MaxCPU = 4
	cfg.InputLog.Enabled = true
	cfg.InputLog.Path = filepath.Join(filepath.Dir(path), "input-log")
	cfg.InputLog.SegmentSize = 16 << 20
	listen, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	cfg.Carbonserver.Listen = listen.Addr().String()
	listen.Close()
	cfg.Carbonserver.TrieIndex = true
	cfg.Carbonserver.TrigramIndex = false
	cfg.Carbonserver.ConcurrentIndex = true
	cfg.Carbonserver.RealtimeIndex = 100
	cfg.Carbonserver.ScanFrequency = &Duration{time.Hour}
	writeSharedConfig(t, path, cfg)
	app := New(path)
	if err := app.ParseConfig(); err != nil {
		t.Fatal(err)
	}
	if err := app.Start(); err != nil {
		t.Fatal(err)
	}
	defer app.Stop()
	app.Carbonserver.WaitForWarmup()
	waitCopy(t, func() bool { return app.Carbonserver.CurrentFileIndex() != nil })
	client := &storecopy.Client{URL: "http://" + cfg.Buckyd.Bind}
	// The configured :0 Buckyd listener is already real; expose the same handler
	// on a known local port for this measurement.
	admin, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	server := &http.Server{Handler: app.Buckyd.Handler(), ReadHeaderTimeout: time.Second}
	defer server.Close()
	go server.Serve(admin)
	client.URL = "http://" + admin.Addr().String()
	manifest, err := client.Manifest(context.Background(), "begin", "")
	if err != nil {
		t.Fatal(err)
	}
	defer client.Manifest(context.Background(), "release", manifest.ID)
	root, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	var bytes int64
	for _, file := range manifest.Files {
		bytes += file.Size
	}
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Second)
	defer cancel()
	for _, reads := range []bool{false, true} {
		readCtx, stopReads := context.WithCancel(ctx)
		var wg sync.WaitGroup
		var count, failed atomic.Int64
		ready := make(chan struct{})
		var once sync.Once
		if reads {
			for worker := range 8 {
				wg.Go(func() {
					httpClient := &http.Client{Timeout: 5 * time.Second}
					ticker := time.NewTicker(4 * time.Millisecond)
					defer ticker.Stop()
					seed := uint64(worker + 1)
					for {
						select {
						case <-readCtx.Done():
							return
						case <-ticker.C:
						}
						seed ^= seed << 13
						seed ^= seed >> 7
						seed ^= seed << 17
						name := fmt.Sprintf("synthetic.production.cluster.service.%08d.cpu.usage", seed%1000000)
						now := time.Now().Unix()
						request, err := http.NewRequestWithContext(readCtx, http.MethodGet, fmt.Sprintf("http://%s/render/?target=%s&from=%d&until=%d&format=json", cfg.Carbonserver.Listen, name, now-3600, now), nil)
						if err != nil {
							failed.Add(1)
							continue
						}
						response, err := httpClient.Do(request)
						if err != nil {
							if readCtx.Err() == nil {
								failed.Add(1)
							}
							continue
						}
						io.Copy(io.Discard, response.Body)
						response.Body.Close()
						if response.StatusCode != http.StatusOK {
							failed.Add(1)
						} else {
							if count.Add(1) >= 100 {
								once.Do(func() { close(ready) })
							}
						}
					}
				})
			}
			select {
			case <-ready:
			case <-ctx.Done():
				t.Fatal("carbonserver reads never became ready")
			}
		}
		for iteration := range 3 {
			var before, after syscall.Rusage
			syscall.Getrusage(syscall.RUSAGE_SELF, &before)
			started := time.Now()
			priorReads := count.Load()
			destination := filepath.Join(root, fmt.Sprintf("%t-%d", reads, iteration))
			if err := client.Pull(ctx, destination, manifest.ID, storecopy.PullOptions{Workers: 16, Chunk: 16 << 20, Apply: true}); err != nil {
				t.Fatal(err)
			}
			elapsed := time.Since(started).Seconds()
			syscall.Getrusage(syscall.RUSAGE_SELF, &after)
			cpu := func(r syscall.Rusage) float64 { return float64(r.Utime.Nano()+r.Stime.Nano()) / 1e9 }
			row := map[string]any{"reads": reads, "iteration": iteration, "bytes": bytes, "seconds": elapsed, "MB_per_second": float64(bytes) / elapsed / 1e6, "cpu_seconds_per_GB": (cpu(after) - cpu(before)) / (float64(bytes) / 1e9), "http_reads_per_second": float64(count.Load()-priorReads) / elapsed, "read_errors": failed.Load()}
			data, _ := json.Marshal(row)
			t.Log(string(data))
			os.RemoveAll(destination)
		}
		stopReads()
		wg.Wait()
		if failed.Load() != 0 {
			t.Fatal("read errors", failed.Load())
		}
	}
}
